<form method="post" class="grid gap-4 rounded-3xl border border-white/10 bg-white/5 p-6 md:grid-cols-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label class="field">Store URL<input name="store_url" placeholder="https://example.com"></label><label class="field">Consumer Key<input name="consumer_key"></label><label class="field">Consumer Secret<input name="consumer_secret"></label><label class="field">Limit<input type="number" name="limit" value="12"></label><label class="field">Vendor<select name="vendor_id"><?php foreach ($vendors as $vendor): ?><option value="<?= (int)$vendor['id'] ?>"><?= e($vendor['store_name']) ?></option><?php endforeach; ?></select></label><label class="field">Category<select name="category_id"><?php foreach ($categories as $category): ?><option value="<?= (int)$category['id'] ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label><button class="rounded-2xl bg-cyan-300 p-4 font-black text-slate-950 md:col-span-2">Import WooCommerce Products</button></form><div class="mt-6 overflow-x-auto rounded-3xl border border-white/10 bg-white/5"><table class="admin-table"><tr><th>Store</th><th>Count</th><th>Status</th><th>Message</th></tr><?php foreach ($imports as $import): ?><tr><td><?= e($import['store_url']) ?></td><td><?= (int)$import['imported_count'] ?></td><td><?= e($import['status']) ?></td><td><?= e($import['message']) ?></td></tr><?php endforeach; ?></table></div>
